H,W=13,19
out=[[6]*W for _ in range(H)]
# Four 5x5 panels at their input locations.
for r in range(1,6):
    for c in range(7,12): out[r][c]=1
    for c in range(13,18): out[r][c]=3
for r in range(7,12):
    for c in range(7,12): out[r][c]=7
    for c in range(13,18): out[r][c]=5
# Replace the centered 3x3 matching motif with background 6.
patterns={
    1:[[0,0,1],[1,1,1],[0,0,1]],
    3:[[0,1,1],[0,1,1],[1,0,0]],
    7:[[0,1,1],[1,1,0],[0,0,1]],
    5:[[0,1,1],[1,1,0],[0,1,1]],
}
blocks={1:(1,7),3:(1,13),7:(7,7),5:(7,13)}
for color,pat in patterns.items():
    r0,c0=blocks[color]
    for i,row in enumerate(pat):
        for j,v in enumerate(row):
            if v: out[r0+1+i][c0+1+j]=6
import json
print(json.dumps(out,separators=(',',':')))
for row in out: print(row)
